<?php
namespace App\Services\Marketing;
use App\Models\{MarketingProject,MarketingTemplateRun,MarketingTemplateGrant,MarketingTemplateCall,MarketingRevision,MarketingVideoFilm,Product};
use App\Jobs\MarketingTemplateJob;
use Illuminate\Support\Facades\{DB,Storage};

class MarketingTemplateWorkflow
{
 public function grant(MarketingProject $p,bool $allowExpired=false):?MarketingTemplateGrant{
  $lang=($p->preferences['language']??null)==='English'?'en':'zh';
  return MarketingTemplateGrant::where('owner_id',$p->owner_id)->where('product_id',$p->product_id)->where('active',true)->when(!$allowExpired,fn($q)=>$q->where('expires_at','>',now()))->latest()->get()->first(function($g)use($p,$lang){$policy=$g->policy;if(isset($policy['project_id']))return $policy['project_id']===$p->id;return !isset($policy['projects'][$lang])||$policy['projects'][$lang]===$p->id;});
 }
 public function busy(MarketingProject $p):bool{return MarketingTemplateRun::where('project_id',$p->id)->whereIn('status',['queued','planning','checking','queued_production','queued_recovery','producing','rendering'])->exists();}
 public function brief(MarketingProject $p,array $d):void{DB::transaction(function()use($p,$d){$p=MarketingProject::lockForUpdate()->findOrFail($p->id);abort_if($this->busy($p)||(int)$p->version!==(int)$d['version'],409,'任务处理中或资料已更新。');$p->update(['brief'=>array_replace($p->brief,['goal'=>$d['goal'],'audience'=>$d['audience']??'','facts'=>$d['request']??'','request'=>$d['request']??'']),'version'=>$p->version+1]);});}
 public function start(MarketingProject $p,array $d,?MarketingTemplateRun $parent=null):MarketingTemplateRun{
  return DB::transaction(function()use($p,$d,$parent){
   $p=MarketingProject::lockForUpdate()->findOrFail($p->id);$old=MarketingTemplateRun::where('project_id',$p->id)->where('request_id',$d['request_id'])->first();if($old)return $old;
   abort_if($this->busy($p)||(int)$p->version!==(int)$d['version'],409,'任务处理中或资料已更新。');
   abort_if(!$parent&&MarketingTemplateRun::where('project_id',$p->id)->exists(),409,'已有方案，请通过修改入口保留版本。');
   $pref=$p->preferences;abort_unless($p->template_id===MarketingTemplateProjects::ID&&$p->template_version===MarketingTemplateProjects::VERSION&&$p->source_type==='product'&&in_array($pref['language']??null,['English','zh-MY'],true)&&(string)($pref['duration']??'')==='15'&&($pref['video_type']??null)==='product_showcase'&&is_array($pref['formats']??null)&&count($pref['formats'])>0&&!array_diff($pref['formats'],['landscape','portrait'])&&is_bool($pref['narration']??null)&&is_bool($pref['subtitles']??null)&&(!$pref['subtitles']||$pref['narration']),422,'制作偏好不符合当前模板。');
   $g=$this->grant($p);abort_unless($g,409,'此商品尚未获得本次测试授权。');$g=MarketingTemplateGrant::lockForUpdate()->findOrFail($g->id);$policy=$g->policy;$lang=$p->preferences['language']==='English'?'en':'zh';
   $bound=$policy['projects'][$lang]??null;abort_if($bound&&$bound!==$p->id,409,'本次授权已绑定该语言的项目。');
   if($parent){abort_unless($parent->project_id===$p->id&&in_array($parent->status,['planned','completed','paused'],true),409);abort_if(($policy['corrections'][$lang]??0)>=max(1,(int)($policy['max_corrections_per_language']??1)),409,'本语言修订额度已用完。');$policy['corrections'][$lang]=($policy['corrections'][$lang]??0)+1;$p->update(['version'=>$p->version+1]);}
   $policy['projects'][$lang]=$p->id;$g->update(['policy'=>$policy]);
   $product=Product::with('images')->findOrFail($p->product_id);$asset=app(MarketingTemplateAssets::class)->primary($product);
   $facts=['name'=>$product->title];foreach(['brand','subtitle','description'] as $field){$value=trim(strip_tags((string)($product->$field??'')));if($value!=='')$facts[$field]=$value;}foreach(($product->features??[]) as $index=>$feature){$value=is_scalar($feature)?(string)$feature:json_encode($feature,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);if(trim($value)!=='')$facts['feature_'.$index]=strip_tags($value);}
   $packet=app(MarketingTemplateContract::class)->call('packet',['product'=>['id'=>(string)$product->id,'name'=>$product->title,'description'=>strip_tags($product->description??''),'facts'=>$facts],'assets'=>[$asset],'template_id'=>MarketingTemplateProjects::ID,'language'=>$lang,'goal'=>$p->brief['goal']]);
   $packet['brand']=trim((string)($product->brand??''));$packet['catalog_data_kind']=in_array('marketing_test_data',$product->tags??[],true)?'test_sample':'merchant_catalog';
   $packet['user_requirements']=['audience'=>$p->brief['audience']??'','request'=>$d['request']??$p->brief['facts']??''];
   $input=['project_version'=>$p->version,'packet'=>$packet,'asset_index'=>['primary'=>$asset],'preferences'=>['formats'=>$p->preferences['formats'],'narration'=>(bool)$p->preferences['narration'],'subtitles'=>(bool)$p->preferences['subtitles'],'music'=>true],'feedback'=>$parent?['request'=>$d['request'],'previous_draft'=>$parent->draft]:null];
   $run=MarketingTemplateRun::create(['project_id'=>$p->id,'owner_id'=>$p->owner_id,'grant_id'=>$g->id,'request_id'=>$d['request_id'],'input_digest'=>MarketingTemplateProjects::hash($input),'input'=>$input,'status'=>'queued','phase'=>'等待编排','corrections'=>$parent?1:0]);MarketingTemplateJob::dispatch($run->id,'plan')->onQueue('marketing-template')->afterCommit();return $run;
  });
 }
 public function refreshQuote(MarketingProject $p,array $d):void{DB::transaction(function()use($p,$d){$p=MarketingProject::lockForUpdate()->findOrFail($p->id);$r=MarketingTemplateRun::where('project_id',$p->id)->where('owner_id',$p->owner_id)->lockForUpdate()->findOrFail($d['run_id']);abort_unless(!$this->busy($p)&&(int)$p->version===(int)$d['version']&&(int)($r->input['project_version']??0)===(int)$p->version&&$r->status==='planned'&&($r->checks['status']??'')==='pass'&&hash_equals($r->input_digest,MarketingTemplateProjects::hash($r->input))&&hash_equals($r->quote['draft_hash']??'',MarketingTemplateProjects::hash($r->draft)),409,'方案已改变，请重新核对。');abort_unless(app(MarketingTemplateRuntime::class)->ready(),409,'制作工具尚未就绪。');$g=MarketingTemplateGrant::where('owner_id',$p->owner_id)->where('active',true)->findOrFail($r->grant_id);$summary=app(MarketingTemplateBilling::class)->summary($g->id);abort_if($summary['unknown']||$summary['reserved_microusd']>=$g->cap_microusd,409,'费用待核对或预算已用完。');app(MarketingProductTemplateRenderer::class)->validateDraft($r);$this->quote($r);});}
 public function produce(MarketingProject $p,array $d):void{DB::transaction(function()use($p,$d){$p=MarketingProject::lockForUpdate()->findOrFail($p->id);$r=MarketingTemplateRun::where('project_id',$p->id)->lockForUpdate()->findOrFail($d['run_id']);abort_unless((int)$p->version===(int)$d['version']&&hash_equals($r->quote['digest']??'', $d['quote_digest']),409,'报价已改变。');if(in_array($r->status,['queued_production','queued_recovery','producing','rendering','completed'],true))return;abort_unless($r->status==='planned'&&now()->lt($r->quote['expires_at']),409,'请重新核对报价。');$r->update(['status'=>'queued_production','phase'=>'等待制作']);MarketingTemplateJob::dispatch($r->id,'produce')->onQueue('marketing-template')->afterCommit();});}
 private function llm(MarketingTemplateRun $r,string $stage,array $payload):array{$receipt=app(MarketingTemplateBilling::class)->call($r,$stage,'llm',$payload,MarketingTemplateProvider::LLM_RESERVE_MICROUSD,fn($id)=>app(MarketingTemplateProvider::class)->llm($payload,$id));$raw=$receipt['data'];$text='';foreach($raw['output']??[] as $item)foreach($item['content']??[] as $c)if(($c['type']??'')==='output_text')$text.=$c['text'];return ['value'=>json_decode($text,true,64,JSON_THROW_ON_ERROR),'id'=>$raw['id']??null];}
 private function plan(MarketingTemplateRun $r,?array $feedback=null,int $attempt=0):void{
  if(!app(MarketingTemplateRuntime::class)->ready())throw new \RuntimeException('template_runtime_not_ready');$c=app(MarketingTemplateContract::class);$i=$r->input;$r->update(['status'=>'planning','phase'=>'AI 正在编排文案与节奏']);$args=['packet'=>$i['packet'],'asset_index'=>$i['asset_index'],'feedback'=>$feedback??$i['feedback']??null];
  $reply=$this->llm($r,'creative-'.$attempt,$c->call('creative',$args));$v=$c->call('validate',['packet'=>$i['packet'],'response'=>$reply['value']]);if($this->recordPlanningDecision($r,$reply['value'],$v))return;
  if(($v['status']??'')!=='awaiting_semantic_check')throw new \RuntimeException('creative_contract_rejected');$draft=$reply['value']['draft'];$r->update(['draft'=>$draft,'status'=>'checking','phase'=>'正在核对商品事实与节奏']);$fitIssue=null;try{app(MarketingProductTemplateRenderer::class)->validateDraft($r->fresh());}catch(\RuntimeException $e){if($e->getMessage()!=='text_does_not_fit_template')throw $e;$fitIssue=['field'=>'copy','reason'=>'Shorten all displayed headings, support and detail copy to fit actual landscape and portrait text regions.','source_ids'=>[]];}
  $review=$this->llm($r,'checker-'.$attempt,$c->call('checker',$args+['draft'=>$draft]));$check=$c->call('check_result',['packet'=>$i['packet'],'draft'=>$draft,'result'=>$review['value'],'provider_response_id'=>$review['id']]);$r->update(['checks'=>$check]);
  if(($check['status']??'')!=='pass'||$fitIssue){
   if($attempt===0&&$this->claimCorrection($r)){ $this->plan($r,['issues'=>array_merge($check['issues']??[],$fitIssue?[$fitIssue]:[]),'previous_draft'=>$draft],1);return; }
   throw new \RuntimeException($fitIssue?'text_does_not_fit_template':'semantic_check_rejected');
  }
  $this->quote($r->fresh());
 }
 private function claimCorrection(MarketingTemplateRun $r):bool{return DB::transaction(function()use($r){$g=MarketingTemplateGrant::lockForUpdate()->findOrFail($r->grant_id);$p=$g->policy;if(($p['automatic_corrections']??true)===false)return false;$lang=$r->input['packet']['language'];if(($p['corrections'][$lang]??0)>=1)return false;$p['corrections'][$lang]=1;$g->update(['policy'=>$p]);$r->update(['corrections'=>1]);return true;});}
 private function quote(MarketingTemplateRun $r):void{$g=MarketingTemplateGrant::findOrFail($r->grant_id);$s=app(MarketingTemplateBilling::class)->summary($g->id);$q=['cap_microusd'=>min(150000,$g->cap_microusd-$s['reserved_microusd']),'planning_actual_microusd'=>$s['actual_microusd'],'model'=>MarketingTemplateProvider::MODEL,'voice'=>['name'=>($r->input['packet']['language']??'en')==='zh'?'Shan Shan':'Bella'],'expires_at'=>now()->addHours(6)->toIso8601String(),'draft_hash'=>MarketingTemplateProjects::hash($r->draft),'description'=>'仅独立配音与本地渲染；原图保留，不调用生图或视频生成 API。'];$q['digest']=MarketingTemplateProjects::hash($q);$r->update(['quote'=>$q,'status'=>'planned','phase'=>'方案已完成，待确认制作']);}
 private function render(MarketingTemplateRun $r):void{
  if(!app(MarketingTemplateRuntime::class)->ready())throw new \RuntimeException('template_runtime_not_ready');$i=$r->input;app(MarketingProductTemplateRenderer::class)->validateDraft($r);$r->update(['status'=>'producing','phase'=>'正在制作独立口播']);$voice=$r->result['voice']??null;
  if($i['preferences']['narration']&&!$voice){
   $text=$r->draft['narration']['text'];if(mb_strlen($text)>300)throw new \RuntimeException('voice_text_too_long');$payload=['voice_id'=>$r->draft['narration']['voice_id'],'text'=>$text,'model_id'=>'eleven_multilingual_v2'];
   $receipt=app(MarketingTemplateBilling::class)->call($r,'voice-'.$r->corrections,'tts',$payload,mb_strlen($text)*80,fn($id)=>app(MarketingTemplateProvider::class)->tts($payload,$id));$data=$receipt['data'];$audio=base64_decode($data['audio_base64']??'',true);if(!$audio)throw new \RuntimeException('voice_response_invalid');
   $path='marketing-template-runs/'.$r->id.'/voice-'.$r->corrections.'.mp3';$disk=Storage::disk('local');$disk->makeDirectory(dirname($path));if($disk->exists($path)&&hash('sha256',$audio)!==hash_file('sha256',$disk->path($path)))throw new \RuntimeException('voice_file_conflict');if(!$disk->exists($path))$disk->put($path,$audio);
   $voice=['path'=>$path,'sha256'=>hash('sha256',$audio),'alignment'=>$data['alignment']??null,'actual_microusd'=>$receipt['actual_microusd']];
  }
  $r->update(['result'=>array_replace($r->result??[],['voice'=>$voice]),'status'=>'rendering','phase'=>'正在合成横屏与竖屏']);
  // Read the persisted JSON representation: timestamps such as 0.0 normalize to 0 in storage.
  $r=$r->fresh();$i=$r->input;$voice=$r->result['voice']??null;
  $task=['version'=>'product-template-task-v1','subject'=>['type'=>'template_run','id'=>$r->id,'project_id'=>$r->project_id,'owner_id'=>$r->owner_id],'source_digest'=>$r->input_digest,'packet'=>$i['packet'],'asset_index'=>$i['asset_index'],'draft'=>$r->draft,'formats'=>$i['preferences']['formats'],'subtitles'=>$i['preferences']['subtitles'],'music'=>$i['preferences']['music'],'voice'=>$voice];
  try{$out=app(MarketingProductTemplateRenderer::class)->execute($task);}catch(\RuntimeException $e){if($e->getMessage()==='voice_overrun'&&$this->claimCorrection($r)){$this->plan($r,['request'=>'Shorten narration to fit actual spoken duration under14 seconds. Preserve facts.','previous_draft'=>$r->draft],1);$r=$r->fresh();if($r->status==='planned'){$this->render($r);return;}}throw $e;}
  DB::transaction(function()use($r,$out,$voice){$p=MarketingProject::lockForUpdate()->findOrFail($r->project_id);abort_unless($p->version===$r->input['project_version'],409);$revision=MarketingRevision::create(['project_id'=>$p->id,'actor_id'=>$p->owner_id,'number'=>($p->revisions()->max('number')??0)+1,'document'=>$r->draft,'context'=>['production_recipe'=>'product-template-v1','run_id'=>$r->id],'confirmed_by'=>$p->owner_id,'confirmed_at'=>now()]);$first=reset($out['formats']);$film=MarketingVideoFilm::create(['project_id'=>$p->id,'owner_id'=>$p->owner_id,'revision_id'=>$revision->id,'fingerprint'=>$r->input_digest,'status'=>'completed','input'=>['template_run'=>$r->id],'result'=>$out,'output_path'=>$first['path'],'output_sha256'=>$first['sha256']]);$r->update(['result'=>array_replace($r->result??[],$out,['voice'=>$voice,'voice_timing'=>$out['voice']??null,'film_id'=>$film->id]),'status'=>'completed','phase'=>'视频已完成']);$p->update(['stage'=>'finished','status'=>'ready','current_revision_id'=>$revision->id]);});
 }
 public function execute(string $id,string $action):void{
  $r=MarketingTemplateRun::findOrFail($id);$expected=$action==='plan'?'queued':($action==='resume'?'queued_recovery':'queued_production');
  if($action==='resume'&&(empty($r->result['voice'])||app(MarketingTemplateBilling::class)->summary($r->grant_id)['unknown']||!app(MarketingTemplateVoice::class)->known($r)))return;
  $claimed=MarketingTemplateRun::whereKey($id)->where('status',$expected)->update(['status'=>$action==='plan'?'planning':'producing','error'=>null]);if(!$claimed)return;$r=$r->fresh();
  try{if(!hash_equals($r->input_digest,MarketingTemplateProjects::hash($r->input)))throw new \RuntimeException('source_digest_changed');$action==='plan'?$this->plan($r):$this->render($r);}catch(\Throwable $e){$this->pause($r,$e);}
 }
 public function recordPlanningDecision(MarketingTemplateRun $r,array $response,array $validation):bool{
  $status=$validation['status']??null;if(!in_array($status,['needs_input','unsupported'],true)||($response['decision']??null)!==$status)return false;
  $r->update(['checks'=>$validation,'result'=>array_replace($r->result??[],['planning_response'=>$response])]);
  $this->pause($r,new \RuntimeException($status==='needs_input'?'product_information_required':'template_request_unsupported'));return true;
 }
 public function pause(MarketingTemplateRun $r,\Throwable $e):void{$raw=$e instanceof \RuntimeException?$e->getMessage():'';$code=preg_match('/^[a-z0-9_]{1,80}$/D',$raw)?$raw:'execution_error';$allowed=['provider_outcome_unknown','provider_cost_unknown','creative_contract_rejected','semantic_check_rejected','voice_overrun','voice_text_too_long','text_does_not_fit_template','template_local_render_failed','template_local_attempt_incomplete'];$r->update(['status'=>'paused','phase'=>'制作已暂停，已有内容保留','error'=>['code'=>$code,'message'=>match($code){'product_information_required'=>'现有商品资料不足以支持本次要求。请补充已核实的商品资料，或调整展示要求。本次已停止，不自动重试。','template_request_unsupported'=>'当前模板无法满足本次要求，已有资料保留；本次已停止，不自动重试。','template_runtime_not_ready'=>'制作工具尚未就绪，任务已暂停；未开始新的收费请求，请联系管理员。','text_does_not_fit_template'=>'文案超出模板文字区域，已在配音前暂停。原图与方案保留，不会自动追加收费。',default=>'本次任务未能安全完成，已暂停；不会自动重试或新增收费。'},'reference'=>$r->id]]);report(new \RuntimeException('template_run_paused:'.$r->id.':'.($r->error['code']??'execution_error')));}
}
